// 按鈕去彈跳（debounce）範例
// 按一下切換 LED 的亮／滅

const int buttonPin = 2;
const int ledPin = 13;

int ledState = LOW;           // LED 目前狀態
int buttonState;              // 目前讀到的按鈕狀態
int lastButtonState = HIGH;   // 上一次讀到的狀態

unsigned long lastDebounceTime = 0;   // 上次狀態變化的時間
unsigned long debounceDelay = 50;     // 去彈跳時間（毫秒）

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);   // 使用內部上拉電阻
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, ledState);
}

void loop() {
  int reading = digitalRead(buttonPin);

  // 只要讀值有變化就重新計時
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  // 狀態穩定超過 debounceDelay 才算數
  if ((millis() - lastDebounceTime) > debounceDelay) {
    if (reading != buttonState) {
      buttonState = reading;

      // 使用上拉電阻，按下時是 LOW
      if (buttonState == LOW) {
        ledState = !ledState;
        digitalWrite(ledPin, ledState);
      }
    }
  }

  lastButtonState = reading;
}

