#include <EEPROM.h>

// 把設定值存到 EEPROM，重開機後不會消失
// 從序列埠輸入 0~255 可以改變 LED 亮度

const int ledPin = 9;
const int addrBrightness = 0;    // EEPROM 位址
const int addrMagic = 1;         // 判斷是否曾經寫入過
const byte MAGIC_VALUE = 42;

int brightness = 128;

void setup() {
  Serial.begin(9600);
  pinMode(ledPin, OUTPUT);

  // 讀取魔術數字判斷 EEPROM 是不是空的
  byte magic = EEPROM.read(addrMagic);

  if (magic == MAGIC_VALUE) {
    brightness = EEPROM.read(addrBrightness);
    Serial.print("Loaded brightness: ");
    Serial.println(brightness);
  } else {
    // 第一次使用，寫入預設值
    EEPROM.write(addrMagic, MAGIC_VALUE);
    EEPROM.write(addrBrightness, brightness);
    Serial.println("First run, using default brightness");
  }

  analogWrite(ledPin, brightness);
  Serial.println("Enter a value 0-255 to change brightness:");
}

void loop() {
  if (Serial.available() > 0) {
    int value = Serial.parseInt();

    if (value >= 0 && value <= 255) {
      brightness = value;
      analogWrite(ledPin, brightness);

      // 只在數值不同時才寫入，減少 EEPROM 磨損
      if (EEPROM.read(addrBrightness) != brightness) {
        EEPROM.write(addrBrightness, brightness);
      }

      Serial.print("Brightness set to ");
      Serial.println(brightness);
    }
  }
}

