// ENA 接 PWM 腳位，IN1/IN2 控制轉向

const int enA = 5;    // PWM 控制轉速
const int in1 = 6;
const int in2 = 7;
const int relayPin = 8;

int motorSpeed = 200;

void setup() {
  pinMode(enA, OUTPUT);
  pinMode(in1, OUTPUT);
  pinMode(in2, OUTPUT);
  pinMode(relayPin, OUTPUT);

  Serial.begin(9600);

  // 開啟繼電器供電
  digitalWrite(relayPin, HIGH);
  Serial.println("Motor control ready");
}

// 正轉
void forward(int speed) {
  digitalWrite(in1, HIGH);
  digitalWrite(in2, LOW);
  analogWrite(enA, speed);
}

// 反轉
void backward(int speed) {
  digitalWrite(in1, LOW);
  digitalWrite(in2, HIGH);
  analogWrite(enA, speed);
}

// 停止
void stopMotor() {
  digitalWrite(in1, LOW);
  digitalWrite(in2, LOW);
  analogWrite(enA, 0);
}

void loop() {
  Serial.println("Forward");
  forward(motorSpeed);
  delay(3000);

  Serial.println("Stop");
  stopMotor();
  delay(1000);

  Serial.println("Backward");
  backward(motorSpeed);
  delay(3000);

  Serial.println("Stop");
  stopMotor();
  delay(1000);

  // 加速測試
  for (int speed = 100; speed <= 255; speed += 5) {
    forward(speed);
    delay(50);
  }
  stopMotor();
  delay(1000);
}

