// ESP32 網頁伺服器：用瀏覽器控制 LED

const char* ssid = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASSWORD";

WiFiServer server(80);

const int ledPin = 2;    // ESP32 開發板上的內建 LED
String ledState = "off";

void setup() {
  Serial.begin(115200);

  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, LOW);

  Serial.print("Connecting to WiFi");
  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println("");
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());

  server.begin();
}

void loop() {
  WiFiClient client = server.available();

  if (client) {
    Serial.println("New client connected");
    String currentLine = "";
    String header = "";

    while (client.connected()) {
      if (client.available()) {
        char c = client.read();
        header += c;

        if (c == '\n') {
          // 連續兩個換行代表 HTTP 請求結束
          if (currentLine.length() == 0) {
            // 判斷要開燈還是關燈
            if (header.indexOf("GET /led/on") >= 0) {
              ledState = "on";
              digitalWrite(ledPin, HIGH);
            } else if (header.indexOf("GET /led/off") >= 0) {
              ledState = "off";
              digitalWrite(ledPin, LOW);
            }

            // 回傳 HTTP 標頭
            client.println("HTTP/1.1 200 OK");
            client.println("Content-type:text/html");
            client.println("Connection: close");
            client.println();

            // 回傳網頁內容
            client.println("<!DOCTYPE html><html>");
            client.println("<head><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"></head>");
            client.println("<body><h1>ESP32 LED Control</h1>");
            client.print("<p>LED is ");
            client.print(ledState);
            client.println("</p>");
            client.println("<p><a href=\"/led/on\"><button>ON</button></a></p>");
            client.println("<p><a href=\"/led/off\"><button>OFF</button></a></p>");
            client.println("</body></html>");
            client.println();
            break;
          } else {
            currentLine = "";
          }
        } else if (c != '\r') {
          currentLine += c;
        }
      }
    }

    client.stop();
    Serial.println("Client disconnected");
  }
}

